const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = input[0];
const positions = [];
let total = 0;

for (let i = 0; i < n; i++) {
  positions.push(total);
  total += input[i + 1];
}

if (total % 2 !== 0) {
  console.log('N');
} else {
  const half = total / 2;
  const trees = new Set(positions);
  let pairs = 0;

  for (const p of positions) {
    if (p < half && trees.has(p + half)) {
      pairs++;
      if (pairs >= 2) break;
    }
  }

  console.log(pairs >= 2 ? 'S' : 'N');
}
